use verus::prelude::*;

// has_prefix(v, p) returns true exactly when p is a prefix of v
#[requires(true)]
#[ensures(|res: bool|  
    // res is true iff p.len() <= v.len() and for all i < p.len(), v[i] == p[i]
    res == (p.len() <= v.len() &&
            forall |i: usize| i < p.len() ==> v[i] == p[i])
)]
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // An empty prefix always matches
    if p.is_empty() {
        return true;
    }
    // If v is shorter than p, it can't start with p
    if v.len() < p.len() {
        return false;
    }
    // Compare element‐by‐element up to p.len()
    v.iter()
     .zip(p.iter())
     .all(|(vc, pc)| vc == pc)
}

// filter_by_prefix(xs, p) returns exactly those vectors from xs
// that have p as a prefix, in the same order
#[requires(true)]
#[ensures(|res: Vec<Vec<char>>|
    // Every element of the result has the prefix p
    (forall |i: usize| i < res.len() ==> has_prefix(&res[i], &p))
    &&
    // And for each element x in xs, x has prefix p iff x is in the result
    (forall |j: usize| j < xs.len() ==>
        (has_prefix(&xs[j], &p) <==> res.contains(xs[j].clone()))
    )
)]
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    // Borrow `p` for each call to has_prefix
    xs.into_iter()
      .filter(|v| has_prefix(v, &p))
      .collect()
}

